217	
218	// Every spelling that MEANS `status` — what a transition out of it has to clear,
219	// since the item may wear any engine's. Leaving a park clears every park spelling
220	// whatever its kind: a re-queue takes the item out of the human's hands entirely.
221	export function spellingsOf(status) {
222	  if (String(status ?? '').startsWith(PARK_PREFIX)) {
223	    return [...PARK_STATUSES, ...PARK_KINDS.map((k) => `task:needs-human-${k}`), NEEDS_HUMAN];
224	  }
225	  const legacy = [...LEGACY_STATUS].filter(([, canonical]) => canonical === status).map(([l]) => l);
226	  return [status, ...legacy];
227	}
228	
229	// A kind word (from a worker's own triage marker, or a call site) to its label.
230	// Anything unrecognised is a `failure`: a worker that misspells its class has a
231	// bug, which is exactly what that lane means.
232	export const triageLabelFor = (kind) =>
233	  (TRIAGE_LABELS.includes(triage(kind)) ? triage(kind) : NEEDS_HUMAN_FAILURE);
234	
235	
236	// The stored-data rename rule, decode side: every spelling ever written maps
237	// STRAIGHT to the canonical word, in one pass — including `outcome:delivered`,
238	// which nothing writes any more but closed issues carry forever.
239	const OUTCOME_WORDS = new Map([[STATUS_DONE, 'done'], [STATUS_REJECTED, 'obsolete']]);
240	
241	// The one outcome an issue's labels carry, as the canonical word ('done',
242	// 'delivered', 'obsolete') or null. Everything that tallies or renders outcomes
243	// decodes through here, so a spelling change is one map entry and not a sweep.
244	export function outcomeOf(issue) {
245	  // `statusesOn` rather than `statusOf`: a closed item's terminal write is its
246	  // outcome even when a park label stands beside it, and park precedence is a
247	  // question about LIVE items — what the queue may pick up — not about history.
248	  const worn = statusesOn(issue);
249	  for (const [status, word] of OUTCOME_WORDS) if (worn.includes(status)) return word;
250	  return hasLabel(issue, OUTCOME_DELIVERED) ? 'delivered' : null;
251	}
252	
253	// --- the request vocabulary, retired (DESIGN §4's legacy table, §16.1) --------
254	// @deprecated The five labels the SHADOW-ITEM request model used. The mark is
255	// `task:origin:ad-hoc` now and the marked issue is the item itself, so nothing here
256	// applies these — but they are read forever: `claude-task` is still accepted as a
257	// mark (a person with it in muscle memory, a template that carries it), and an
258	// issue whose shadow item is still draining wears `claude-queued`.
259	//
260	// What survives the retirement is the reason the mark is a LABEL at all: it must be
261	// appliable from the issue page on a phone, and it is write-gated by the platform —
262	// applying a label needs triage or write access — which is the first half of the
263	// security story (the second is the precondition's permission read at pickup,
264	// §16.4). The parameters that were labels are body fields now, gated on the
265	// author's push access instead (`parseRequestFields`).
266	export const REQUEST_LABEL = 'claude-task';
267	export const QUEUED_LABEL = 'claude-queued';
268	export const IN_REVIEW_LABEL = 'claude-in-review';
269	export const MODEL_LABEL_PREFIX = 'claude-model:';
270	
271	// The merge authorization (§16.11): the asker says up front that this request's
272	// change may land without their approval WHEN ITS DIFF IS NARROW — the run still
273	// judges the diff, and a wide one parks for review exactly as an unauthorized
274	// request does. Consumed with the mark like the model labels, so each ask
275	// authorizes afresh and a label left by an earlier ask never carries into a new one.
276	export const AUTOMERGE_LABEL = 'claude-automerge';
277	
278	// The families a request may ask for, and the one it gets when it asks for
279	// nothing. `none` is not among them: a request is implemented by a session, so an
280	// agentless family would name a run that cannot happen.
281	export const REQUEST_MODELS = Object.freeze(['opus', 'sonnet', 'haiku']);
282	export const DEFAULT_REQUEST_MODEL = 'opus';
283	
284	export const MODEL_LABELS = REQUEST_MODELS.map((f) => `${MODEL_LABEL_PREFIX}${f}`);
285	
286	// @deprecated The set the shadow-item model ensured. Nothing ensures it now — the
287	// entry point is `task:origin:ad-hoc`, which the queue's own set carries — and it
288	// stays exported because a fielded pack version may still import it.
289	export const REQUEST_LABELS = [
290	  { name: REQUEST_LABEL, color: '1d76db', description: 'Claudinite: implement this issue — the next scheduler run queues a run for it' },
291	  { name: QUEUED_LABEL, color: 'fbca04', description: 'Claudinite: a work item exists for this issue' },
292	  { name: IN_REVIEW_LABEL, color: '5319e7', description: 'Claudinite: a pull request is open for this issue, waiting on a person' },
293	  { name: AUTOMERGE_LABEL, color: '0e8a16', description: 'Claudinite: land this request without approval if its diff is narrow (docs, tests, comments, code in one directory)' },
294	  ...REQUEST_MODELS.map((f) => ({
295	    name: `${MODEL_LABEL_PREFIX}${f}`, color: 'ededed',
296	    description: `Claudinite: run this request at the ${f} family`,
297	  })),
298	];
